{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Aromatherapy guidance and retail additions</title>
  <link rel="stylesheet" href="assets/css/styles.css">
  <meta name="description" content="Gentle aromatherapy sessions and curated blends that may support daily ease. Local studio in {{CITY}}, {{STATE}}.">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="logo" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="/services.html">Offerings</a>
        <a href="/blends.html">Blends</a>
        <a href="/shop.html">Shop</a>
        <a href="/pricing.html">Plans</a>
        <a href="/about.html">Our Story</a>
        <a href="/book.html" class="cta">Book a Visit</a>
        <a href="/contact.html">Connect</a>
      </nav>
      <button class="mobile-toggle" aria-label="Open menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <div class="wrap hero-grid">
        <div class="hero-text">
          <h1>Small scent moments that may shift a mood</h1>
          <p class="lead">Gentle aromatherapy sessions, custom blends, and take-home rituals to help you move through busy days with more ease.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/services.html">Explore Offerings</a>
          </div>
        </div>
        <div class="hero-visual" aria-hidden="true">
          <svg class="pattern" viewBox="0 0 600 400" preserveAspectRatio="xMidYMid slice">
            <defs>
              <pattern id="p" width="40" height="40" patternUnits="userSpaceOnUse">
                <circle cx="8" cy="8" r="6" fill="#E8F6F2" />
                <circle cx="28" cy="28" r="6" fill="#F6F3FF" />
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#p)" />
            <g transform="translate(60,40)">
              <path d="M40 120 C20 80, 80 20, 140 60 S220 140, 260 80" stroke="#CDEFE4" stroke-width="12" fill="none" stroke-linecap="round" stroke-linejoin="round" opacity="0.9"/>
              <g transform="translate(140,40)">
                <ellipse cx="60" cy="60" rx="80" ry="40" fill="#F3F9F7" opacity="0.8"/>
              </g>
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- DIAGNOSTIC: Mood-to-Method selector (instance A) -->
    <section class="diagnostic wrap">
      <h2>Where are you right now?</h2>
      <p class="muted">Pick a present mood and we’ll suggest a simple approach you can try in minutes.</p>
      <div class="mood-grid">
        <div class="mood-controls">
          <label class="mood-pill" data-method="grounding">
            <input type="radio" name="moodA" value="grounding" checked>
            <span>Wired</span>
          </label>
          <label class="mood-pill" data-method="clarity">
            <input type="radio" name="moodA" value="clarity">
            <span>Foggy</span>
          </label>
          <label class="mood-pill" data-method="rest">
            <input type="radio" name="moodA" value="rest">
            <span>Tense</span>
          </label>
        </div>
        <div class="mood-result" id="moodResultA">
          <h3 class="approach-title">Grounding Breath & Pocket Inhaler</h3>
          <p class="approach-copy">A short inhalation routine with a grounding blend may support a settled nervous system. We recommend an inhaler to carry the practice with you.</p>
          <a id="moodCtaA" class="btn primary" href="/book.html">Schedule a grounding consult</a>
        </div>
      </div>
    </section>

    <!-- PLAN: Recommended flow + Mood-to-Method selector (instance B) -->
    <section class="plan wrap">
      <div class="plan-inner">
        <div class="plan-text">
          <h2>A simple plan you can use today</h2>
          <p class="muted">Short steps and a take-home blend to extend the session.</p>
          <ol class="plan-steps">
            <li>5–10 minutes intake and scent history.</li>
            <li>Guided inhalation or diffuser session using a tailored blend.</li>
            <li>Take-home vial or inhaler and a two-step micro-habit to repeat.</li>
          </ol>
        </div>
        <div class="plan-panel">
          <h3>Choose your current state</h3>
          <div class="mood-controls small" id="moodB">
            <label class="mood-pill" data-method="focus">
              <input type="radio" name="moodB" value="focus" checked>
              <span>Distracted</span>
            </label>
            <label class="mood-pill" data-method="soften">
              <input type="radio" name="moodB" value="soften">
              <span>Overwhelmed</span>
            </label>
            <label class="mood-pill" data-method="ease">
              <input type="radio" name="moodB" value="ease">
              <span>Low energy</span>
            </label>
          </div>
          <div class="plan-recommendation" id="moodResultB">
            <h4 class="approach-title">Focus Blend + Desk Diffuser</h4>
            <p class="approach-copy">A bright, citrus-forward blend and brief inhalation microsession may support attentive moments. Includes a desk diffuser recommendation.</p>
            <a id="moodCtaB" class="btn ghost" href="/blends.html">See focus blends to try</a>
          </div>
        </div>
      </div>
    </section>

    <!-- MICRO HABITS -->
    <section class="micro-habits wrap">
      <h2>Tiny practices, daily reach</h2>
      <p class="muted">Short actions you can pair with scent—no special setup required.</p>
      <ul class="habits-list">
        <li><strong>30-second inhaler reset</strong> — three slow inhales to center before a meeting.</li>
        <li><strong>Two-scent pairing</strong> — rotate a citrus in the morning and a soft herb in the evening.</li>
        <li><strong>Patch-test ritual</strong> — try a small dilution on the inner arm 24 hours before frequent use.</li>
      </ul>
    </section>

    <!-- PRICING: Pricing Comparator toggle -->
    <section class="pricing wrap">
      <h2>Plans and single-session options</h2>
      <p class="muted">Transparent pricing so you can choose a single visit or a package that may support ongoing ease.</p>

      <div class="pricing-toggle" role="tablist" aria-label="Pricing period">
        <button class="period active" data-period="monthly">Monthly</button>
        <button class="period" data-period="package">Packages</button>
      </div>

      <div class="pricing-grid">
        <div class="card">
          <h3>Intro Session</h3>
          <div class="price"><span class="num" data-monthly="85" data-package="75">$85</span></div>
          <p class="muted">A focused 45-minute consult and starter vial.</p>
          <a class="btn primary" href="/book.html">Book intro</a>
        </div>
        <div class="card">
          <h3>Session Bundle</h3>
          <div class="price"><span class="num" data-monthly="320" data-package="280">$320</span></div>
          <p class="muted">Four 45-minute sessions spread across a month or two.</p>
          <a class="btn primary" href="/pricing.html">Choose bundle</a>
        </div>
        <div class="card">
          <h3>Blend + Inhaler Kit</h3>
          <div class="price"><span class="num" data-monthly="48" data-package="42">$48</span></div>
          <p class="muted">A custom travel vial and inhaler ready to support your micro-habit.</p>
          <a class="btn ghost" href="/shop.html">Shop kit</a>
        </div>
      </div>
    </section>

    <!-- CTA FOOTER -->
    <section class="cta wrap">
      <div class="cta-inner">
        <h2>Ready to try a scent approach?</h2>
        <p class="muted">Book a short consultation or pick a starter kit to begin at home.</p>
        <div class="cta-actions">
          <a class="btn primary" href="/book.html">Book a short consult</a>
          <a class="btn ghost" href="/shop.html">Browse starter kits</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="footer-grid">
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <p class="muted">Serving {{CITY}}, {{STATE}}. Not a replacement for medical care. Our practices may support wellbeing; they are not medical treatments.</p>
        </div>
        <div>
          <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
          <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
        <div>
          <p><a href="/pricing.html">Pricing</a></p>
          <p><a href="/contact.html">Policies & FAQ</a></p>
        </div>
      </div>
      <p class="small muted">Please patch-test before using an essential oil blend on skin. Avoid certain oils during pregnancy and around pets; ask about safety during consultation.</p>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
